pub fn is_non_prime(n: u64) -> bool {
    // By problem statement, n >= 2.
    // 2 and 3 are prime, so they are not non-prime (composite).
    if n <= 3 {
        return false;
    }
    // Even numbers greater than 2 are composite.
    if n % 2 == 0 {
        return true;
    }
    // Test odd divisors from 3 up to sqrt(n).
    // We avoid overflow by testing i <= n / i rather than i*i <= n.
    let mut i = 3;
    while i <= n / i {
        if n % i == 0 {
            return true;
        }
        i += 2;
    }
    // No divisor found means n is prime.
    false
}

